   encode_tags(TagIn, EncBytes, EncLen).

'enc_Record_items_components'([], AccBytes, AccLen) -> 
   {lists:reverse(AccBytes),AccLen};

'enc_Record_items_components'([H|T],AccBytes, AccLen) ->
   {EncBytes,EncLen} = encode_integer(H, [<<2>>]),
   'enc_Record_items_components'(T,[EncBytes|AccBytes], AccLen + EncLen).



dec_Record(Tlv) ->
