Term2 = decode_boolean(V2, [131073]),

%%-------------------------------------------------
%% attribute bytes(3) with type OCTET STRING
%%-------------------------------------------------
[V3|Tlv4] = Tlv3, 
Term3 = decode_octet_string(V3, [131074]),

%%-------------------------------------------------
%% attribute bits(4) with type BIT STRING
%%-------------------------------------------------
[V4|Tlv5] = Tlv4, 
Term4 = decode_native_bit_string(V4, [131075]),

%%-------------------------------------------------
%% attribute name(5) with type IA5String OPTIONAL
%%-------------------------------------------------
{Term5,Tlv6} = case Tlv5 of
[{131076,V5}|TempTlv6] ->
    {begin
binary_to_list(decode_restricted_string(V5, []))
end
, TempTlv6};
    _ ->
        { asn1_NOVALUE, Tlv5}
end,

%%-------------------------------------------------
%% attribute items(6) with type SEQUENCE OF
%%-------------------------------------------------
[V6|Tlv7] = Tlv6, 
Term6 = 'dec_Record_items'(V6, [131077]),

